// Set Today's Sky — the fallback for the sky tracker window.
//
// Everything the tracker UI does is also on the module API, so if a Foundry update ever breaks the window
// the class stays playable from here.

const api = game.modules.get("isaacs-hb-pf2e")?.api;
if (!api) {
    ui.notifications.error("Isaac's Homebrew (PF2e) is not active.");
} else if (!game.user.isGM) {
    ui.notifications.warn("Only the GM can change the sky.");
} else {
    // Just open the tracker if it still works.
    api.open();

    // Or drive it directly — uncomment what you need:
    //
    //   await api.sky.set({ sign: "leo", aspect: "none" });   // Leo is ascendant today
    //   await api.sky.set({ aspect: "exalted" });               // make today a Zenith for the current sign
    //   await api.sky.advanceDay();                             // roll tomorrow from the pre-rolled queue
    //   await api.sky.scheduleZenith("leo", 3);                 // pin Leo Exalted three days out
    //   await api.sky.applyToAll();                             // re-apply boons to every Saint
    //   console.log(api.sky.forecast(3));                       // what Read the Constellation would learn
}
